const KEY='melaten-management-v1',fields=PLAN.fields,ids=new Set(fields.map(f=>f.id)),NS='http://www.w3.org/2000/svg';
let state={schema:1,fields:{},graves:[],tasks:[],updated:null},selected='94',taskFilter='open',layer='work',box={x:0,y:0,w:800,h:888},toastTimer;
function valid(s){return s&&s.schema===1&&s.fields&&typeof s.fields==='object'&&!Array.isArray(s.fields)&&Array.isArray(s.graves)&&Array.isArray(s.tasks)&&s.graves.length<100000&&s.tasks.length<100000&&Object.entries(s.fields).every(([k,v])=>ids.has(k)&&v&&typeof v==='object'&&typeof v.notes==='string'&&['Ungeprüft','In Prüfung','Geprüft'].includes(v.condition))&&s.graves.every(g=>g&&typeof g.id==='string'&&typeof g.number==='string'&&g.number.trim()&&ids.has(g.field)&&['Unbekannt','Frei','Belegt','Reserviert','Aufgelöst'].includes(g.status)&&['name','type','end','notes'].every(k=>typeof g[k]==='string'))&&new Set(s.graves.map(g=>g.id)).size===s.graves.length&&new Set(s.graves.map(g=>g.field+'|'+g.number.toLowerCase())).size===s.graves.length&&s.tasks.every(t=>t&&typeof t.id==='string'&&typeof t.title==='string'&&t.title.trim()&&ids.has(t.field)&&typeof t.done==='boolean'&&['Normal','Hoch'].includes(t.priority)&&['due','notes'].every(k=>typeof t[k]==='string'))&&new Set(s.tasks.map(t=>t.id)).size===s.tasks.length&&DFM.validExtensions(s);}
try{const raw=localStorage.getItem(KEY);if(raw){const s=JSON.parse(raw);if(!valid(s))throw Error();state=s;}}catch(e){setTimeout(()=>toast('Gespeicherte Daten konnten nicht geladen werden. Bitte Sicherung importieren.'),100);}
function persist(next){next.updated=new Date().toISOString();try{localStorage.setItem(KEY,JSON.stringify(next));state=next;return true;}catch(e){toast('Speichern nicht möglich. Browser-Speicher prüfen; Änderungen wurden nicht übernommen.');return false;}}
function change(fn,msg){const next=JSON.parse(JSON.stringify(state));fn(next);if(!persist(next))return false;render();if(msg)toast(msg);return true;}
function uid(){return crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);}
function toast(msg){clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,5500);}
function el(tag,attrs){const e=document.createElementNS(NS,tag);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));return e;}
fields.forEach((f,i)=>{const p=el('polygon',{points:f.points.map(p=>p.join(',')).join(' '),'data-id':f.id,class:'field',role:'button',tabindex:0,'aria-label':'Flurfläche '+f.id});const title=el('title',{});title.textContent='Flurfläche '+f.id+' · '+f.zone;p.append(title);p.addEventListener('click',()=>{if(!wasDragged)select(f.id);});p.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(f.id);}});$('#fieldLayer').append(p);const t=el('text',{x:f.center[0],y:f.center[1],class:'field-label','data-label':f.id});t.textContent=f.id;$('#labels').append(t);});
function select(id){if(!ids.has(id))return;selected=id;renderMap();renderDetail();}
function fieldGraves(id){return state.graves.filter(g=>g.field===id);}function fieldTasks(id){return state.tasks.filter(t=>t.field===id&&!t.done);}
function matches(f){const q=$('#mapSearch').value.trim().toLocaleLowerCase('de'),filter=$('#mapFilter').value;const found=!q||f.id.toLowerCase().includes(q)||fieldGraves(f.id).some(g=>(g.number+' '+g.name).toLowerCase().includes(q));return found&&(filter==='all'||filter==='graves'&&fieldGraves(f.id).length||filter==='tasks'&&fieldTasks(f.id).length||filter==='check'&&state.fields[f.id]?.condition!=='Geprüft'||['expired','soon','heritage'].includes(filter)&&fieldGraves(f.id).some(g=>DFM.matchRecord(g,filter)));}
function renderMap(){let count=0;fields.forEach((f,i)=>{const active=!!matches(f);if(active)count++;const p=$(`[data-id="${f.id}"]`),t=$(`[data-label="${f.id}"]`);p.setAttribute('class','field zone-'+(f.zone==='Erweiterung'?1:f.zone==='Ostteil'?2:0)+(selected===f.id?' selected':'')+(fieldTasks(f.id).length?' has-task':'')+(!active?' dimmed':''));p.setAttribute('aria-pressed',String(selected===f.id));t.setAttribute('class','field-label'+(selected===f.id?' sel':'')+(!active?' dimmed':''));});$('#searchCount').textContent=count+' von '+fields.length+' Flächen';$('#searchCount').hidden=!$('#mapSearch').value&&$('#mapFilter').value==='all';}
function opts(values,current){return values.map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(v)}</option>`).join('');}
function renderDetail(){const f=fields.find(f=>f.id===selected),v=state.fields[selected]||{condition:'Ungeprüft',notes:''},gs=fieldGraves(selected),ts=fieldTasks(selected);$('#detail').innerHTML=`<div class="detailhero"><div class="overline">Ausgewählte Flurfläche</div><h2>Fläche ${esc(f.id)}</h2><p>${esc(f.zone)} · Melaten</p><span class="quality">Schematisch digitalisiert</span></div><div class="detailbody"><div class="detailmetrics"><div><strong>${gs.length}</strong><span>erfasste Gräber</span></div><div><strong>${ts.length}</strong><span>offene Aufgaben</span></div></div><form id="fieldForm"><label class="formlabel">Prüfstatus<select name="condition">${opts(['Ungeprüft','In Prüfung','Geprüft'],v.condition)}</select></label><label class="formlabel">Flächennotizen<textarea name="notes" maxlength="5000" placeholder="Hinweise zur Fläche, Grenzen oder Pflege …">${esc(v.notes)}</textarea></label><button class="btn" type="submit">Änderungen speichern</button></form><button class="btn primary" id="fieldNewGrave">+ Grab in Fläche ${esc(f.id)} erfassen</button><button class="btn" id="fieldNewTask">+ Aufgabe für diese Fläche</button>${gs.length?'<ul class="detailgraves">'+gs.slice(0,5).map(g=>`<li><button data-grave="${esc(g.id)}">${esc(g.number)}</button> · ${esc(g.status)}</li>`).join('')+'</ul>':''}<p class="detailnote">Flächenkennungen aus der Vorlage. Grabpositionen und Belegungszahlen sind nicht aus dem Plan ableitbar. Einträge sind der Fläche zugeordnet.</p></div>`;$('#fieldForm').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);change(s=>s.fields[selected]={condition:d.get('condition'),notes:d.get('notes')},'Fläche gespeichert.');};$('#fieldNewGrave').onclick=()=>graveDialog();$('#fieldNewTask').onclick=()=>taskDialog();$$('[data-grave]').forEach(b=>b.onclick=()=>graveDialog(b.dataset.grave));}
function render(){renderMap();renderDetail();$('#fieldCount').textContent=fields.length;$('#graveCount').textContent=state.graves.length;$('#graveSub').textContent=state.graves.length?state.graves.filter(g=>g.status==='Belegt').length+' als belegt erfasst':'Noch keine Einträge';const open=state.tasks.filter(t=>!t.done);$('#taskCount').textContent=open.length;$('#taskSub').textContent=open.length?open.filter(t=>t.priority==='Hoch').length+' mit hoher Priorität':'Keine offenen Aufgaben';renderGraves();renderTasks();}
function view(name){$$('.view').forEach(e=>e.classList.toggle('active',e.id===name));$$('.nav').forEach(e=>e.classList.toggle('active',e.dataset.view===name));location.hash=name;}
$$('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));window.addEventListener('hashchange',()=>{const n=location.hash.slice(1);if(['karte','register','aufgaben','analyse'].includes(n))view(n);});
function openModal(title,body){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=body;$('#modal').showModal();}$('#closeModal').onclick=()=>$('#modal').close();
function fieldOptions(current){return opts([...ids].sort((a,b)=>a.localeCompare(b,'de',{numeric:true})),current);}
function graveDialog(id){const g=state.graves.find(g=>g.id===id)||{field:selected,number:'',name:'',type:'Unbekannt',status:'Unbekannt',end:'',notes:''};openModal(id?'Grab bearbeiten':'Grab erfassen',`<form id="graveForm"><div class="formgrid"><label class="formlabel">Flurfläche *<select name="field" required>${fieldOptions(g.field)}</select></label><label class="formlabel">Grabnummer *<input name="number" required maxlength="80" value="${esc(g.number)}" placeholder="z. B. Reihe 2 / Grab 15"></label><label class="formlabel full">Name / Bezeichnung<input name="name" maxlength="200" value="${esc(g.name)}" placeholder="Optional"></label><label class="formlabel">Grabart<select name="type">${opts(['Unbekannt','Erdgrab','Urnengrab','Familiengrab','Wahlgrab','Reihengrab','Sonstige'],g.type)}</select></label><label class="formlabel">Status<select name="status">${opts(['Unbekannt','Frei','Belegt','Reserviert','Aufgelöst'],g.status)}</select></label><label class="formlabel full">Nutzungsende<input type="date" name="end" value="${esc(g.end)}"></label><label class="formlabel full">Notizen<textarea name="notes" maxlength="5000">${esc(g.notes)}</textarea></label></div><p class="micro">Zuordnung zur Flurfläche, keine genaue Grabposition. Daten bleiben in diesem Browser.</p><div class="formactions">${id?'<button type="button" id="deleteGrave" class="btn danger">Löschen</button>':''}<button type="button" class="btn cancel">Abbrechen</button><button class="btn primary">Speichern</button></div></form>`);$('.cancel').onclick=()=>$('#modal').close();$('#graveForm').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));Object.keys(data).forEach(k=>data[k]=data[k].trim());if(!data.number)return toast('Bitte eine Grabnummer eingeben.');if(state.graves.some(x=>x.id!==id&&x.field===data.field&&x.number.toLowerCase()===data.number.toLowerCase()))return toast('Diese Grabnummer existiert bereits in der Fläche.');if(!DFM.validExtensions({graves:[data],tasks:[]}))return toast('Bitte gültige Datumsangaben prüfen: Geburt vor Tod, Tod vor Beisetzung.');const next={...g,...data,id:id||uid()};if(change(s=>{if(id)s.graves=s.graves.map(x=>x.id===id?next:x);else s.graves.push(next);},'Grab gespeichert.'))$('#modal').close();};if(id)$('#deleteGrave').onclick=()=>{if(confirm('Diesen Grabeintrag löschen?'))if(change(s=>s.graves=s.graves.filter(x=>x.id!==id),'Grabeintrag gelöscht.'))$('#modal').close();};}
function renderGraves(){const q=$('#graveSearch').value.toLowerCase(),status=$('#graveFilter').value;const rows=state.graves.filter(g=>(!status||g.status===status)&&(g.number+' '+g.name+' '+g.field).toLowerCase().includes(q)&&DFM.matchRecord(g,$('#recordFilter').value));$('#graveRows').innerHTML=rows.map(g=>`<tr><td><strong>${esc(g.number)}</strong></td><td><button data-locate="${esc(g.field)}">${esc(g.field)} ↗</button></td><td>${esc(g.name)||'Nicht angegeben'}</td><td>${esc(g.type)}${g.heritage&&g.heritage!=='Unbekannt'&&g.heritage!=='Kein Merkmal erfasst'?'<br><span class="heritage-label">'+esc(g.heritage)+'</span>':''}</td><td><span class="pill ${esc(g.status)}">${esc(g.status)}</span></td><td>${date(g.end)}</td><td><button data-edit="${esc(g.id)}">Bearbeiten</button></td></tr>`).join('');$('#graveEmpty').hidden=rows.length>0;$('#graveEmpty').querySelector('h3').textContent=state.graves.length?'Keine passenden Einträge.':'Das Register ist bereit.';$('#graveEmpty').querySelector('p').innerHTML=state.graves.length?'Passe die Suche oder den Statusfilter an.':'Die Vorlage enthält keine Belegungsdaten.<br>Erfasse dein erstes Grab und ordne es einer Fläche zu.';$$('[data-edit]').forEach(b=>b.onclick=()=>graveDialog(b.dataset.edit));$$('[data-locate]').forEach(b=>b.onclick=()=>{select(b.dataset.locate);view('karte');focusField(b.dataset.locate);});}
function date(s){if(!s)return 'Nicht angegeben';const d=new Date(s+'T12:00:00');return isNaN(d.getTime())?esc(s):d.toLocaleDateString('de-DE');}
function taskDialog(id){const t=state.tasks.find(t=>t.id===id)||{field:selected,title:'',priority:'Normal',due:'',notes:'',done:false};openModal(id?'Aufgabe bearbeiten':'Aufgabe anlegen',`<form id="taskForm"><label class="formlabel">Aufgabe *<input name="title" required maxlength="200" value="${esc(t.title)}" placeholder="z. B. Flächengrenzen vor Ort prüfen"></label><div class="formgrid"><label class="formlabel">Flurfläche *<select name="field">${fieldOptions(t.field)}</select></label><label class="formlabel">Priorität<select name="priority">${opts(['Normal','Hoch'],t.priority)}</select></label><label class="formlabel full">Fällig am<input type="date" name="due" value="${esc(t.due)}"></label><label class="formlabel full">Beschreibung<textarea name="notes" maxlength="5000">${esc(t.notes)}</textarea></label></div><div class="formactions">${id?'<button type="button" id="deleteTask" class="btn danger">Löschen</button>':''}<button type="button" class="btn cancel">Abbrechen</button><button class="btn primary">Speichern</button></div></form>`);$('.cancel').onclick=()=>$('#modal').close();$('#taskForm').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.title=d.title.trim();if(!d.title)return toast('Bitte einen Aufgabentitel eingeben.');if(!DFM.isDate(d.due))return toast('Bitte ein gültiges Fälligkeitsdatum eingeben.');const next={...t,...d,id:id||uid(),done:d.phase==='Erledigt'};if(change(s=>{if(id)s.tasks=s.tasks.map(x=>x.id===id?next:x);else s.tasks.push(next);},'Aufgabe gespeichert.'))$('#modal').close();};if(id)$('#deleteTask').onclick=()=>{if(confirm('Diese Aufgabe löschen?'))if(change(s=>s.tasks=s.tasks.filter(x=>x.id!==id),'Aufgabe gelöscht.'))$('#modal').close();};}
function renderTasks(){const rows=state.tasks.filter(t=>taskFilter==='all'||(taskFilter==='done'?t.done:!t.done)).sort((a,b)=>(b.priority==='Hoch')-(a.priority==='Hoch')||(a.due||'9999').localeCompare(b.due||'9999'));$('#taskList').innerHTML=rows.length?rows.map(t=>`<article class="taskrow ${t.done?'done':''}"><input type="checkbox" class="taskcheck" data-check="${esc(t.id)}" ${t.done?'checked':''} aria-label="Aufgabe ${esc(t.title)} als erledigt markieren"><div><h3>${esc(t.title)}</h3><p>Fläche ${esc(t.field)}${t.notes?' · '+esc(t.notes):''}</p><p class="taskextra">${esc(t.phase||(t.done?'Erledigt':'Offen'))} · ${esc(t.assignee||'Nicht zugewiesen')}</p></div><div class="taskmeta">${t.priority==='Hoch'?'<span class="urgent">Hohe Priorität</span>':''}<span>${t.due?'Fällig: '+date(t.due):'Ohne Frist'}</span><button class="btn" data-task="${esc(t.id)}">Bearbeiten</button></div></article>`).join(''):'<div class="tablecard empty"><span>✓</span><h3>Keine '+(taskFilter==='done'?'erledigten ':taskFilter==='open'?'offenen ':'')+'Aufgaben.</h3><p>Lege eine Pflegearbeit, Kontrolle oder Datenprüfung an.</p></div>';$$('[data-check]').forEach(b=>b.onchange=()=>change(s=>{const t=s.tasks.find(t=>t.id===b.dataset.check);t.done=b.checked;t.phase=b.checked?'Erledigt':'Offen';},'Aufgabe aktualisiert.'));$$('[data-task]').forEach(b=>b.onclick=()=>taskDialog(b.dataset.task));}
$$('[data-tfilter]').forEach(b=>b.onclick=()=>{taskFilter=b.dataset.tfilter;$$('[data-tfilter]').forEach(x=>x.classList.toggle('active',x===b));renderTasks();});
$('#newGrave').onclick=$('#firstGrave').onclick=()=>graveDialog();$('#newTask').onclick=()=>taskDialog();$('#graveSearch').oninput=$('#graveFilter').onchange=renderGraves;$('#mapSearch').oninput=$('#mapFilter').onchange=renderMap;$('#mapSearch').onkeydown=e=>{if(e.key==='Enter'){const exact=fields.find(f=>f.id.toLowerCase()===$('#mapSearch').value.toLowerCase());const f=exact||fields.find(matches);if(f){select(f.id);focusField(f.id);}}};
function setBox(){box.w=Math.min(1200,Math.max(120,box.w));box.h=box.w*888/800;box.x=Math.max(-250,Math.min(800-box.w+250,box.x));box.y=Math.max(-250,Math.min(888-box.h+250,box.y));$('#map').setAttribute('viewBox',`${box.x} ${box.y} ${box.w} ${box.h}`);}
function zoom(factor,px=box.x+box.w/2,py=box.y+box.h/2){const next=Math.max(120,Math.min(1200,box.w*factor)),f=next/box.w;box.x=px+(box.x-px)*f;box.y=py+(box.y-py)*f;box.w=next;setBox();}
function focusField(id){const f=fields.find(f=>f.id===id);box.w=350;box.x=f.center[0]-175;box.y=f.center[1]-350*888/800/2;setBox();}
$('#zoomIn').onclick=()=>zoom(.8);$('#zoomOut').onclick=()=>zoom(1.25);$('#zoomReset').onclick=()=>{box={x:0,y:0,w:800,h:888};setBox();};
function svgPoint(e){const p=$('#map').createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform($('#map').getScreenCTM().inverse());}
$('#map').addEventListener('wheel',e=>{e.preventDefault();const p=svgPoint(e);zoom(e.deltaY>0?1.12:.89,p.x,p.y);},{passive:false});
let drag=null,wasDragged=false;$('#map').onpointerdown=e=>{if(e.button!==0)return;wasDragged=false;drag={point:svgPoint(e),startX:e.clientX,startY:e.clientY,x:box.x,y:box.y,id:e.pointerId};};$('#map').onpointermove=e=>{if(!drag||drag.id!==e.pointerId)return;if(Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>4){wasDragged=true;$('#map').classList.add('dragging');$('#map').setPointerCapture(e.pointerId);const m=$('#map').getScreenCTM();box.x=drag.x-(e.clientX-drag.startX)/m.a;box.y=drag.y-(e.clientY-drag.startY)/m.d;setBox();}};function endDrag(e){if(!drag)return;drag=null;$('#map').classList.remove('dragging');if($('#map').hasPointerCapture(e.pointerId))$('#map').releasePointerCapture(e.pointerId);setTimeout(()=>wasDragged=false,0);}$('#map').onpointerup=endDrag;$('#map').onpointercancel=endDrag;
$$('[data-layer]').forEach(b=>b.onclick=()=>{layer=b.dataset.layer;$$('[data-layer]').forEach(x=>x.classList.toggle('active',x===b));$('#baseImage').setAttribute('href',layer==='work'?'map-base.svg':layer==='vector'?'melaten-vektor.svg':'original.png');$('#mapViewport').classList.toggle('source',layer!=='work');});
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#backup').onclick=()=>{download('melaten-sicherung-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2),'application/json');toast('Sicherung heruntergeladen. Sie enthält alle lokalen Einträge.');};
$('#import').onclick=()=>$('#importFile').click();$('#importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>20*1024*1024)throw Error();const data=JSON.parse(await file.text());if(!valid(data))throw Error();if(!confirm(`Sicherung mit ${data.graves.length} Gräbern und ${data.tasks.length} Aufgaben importieren? Die aktuellen lokalen Einträge werden ersetzt.`))return;if(persist(data)){render();toast('Sicherung importiert.');}}catch(err){toast('Ungültige Sicherung. Bitte eine passende Melaten-JSON-Datei bis 20 MB wählen.');}finally{e.target.value='';}};
$('#exportCsv').onclick=()=>{const keys=['number','field','name','type','status','end','birth','death','burial','heritage','heritageSource','notes'];const cell=v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replace(/"/g,'""')+'"';const rows=[['Grabnummer','Flurfläche','Name','Grabart','Status','Nutzungsende','Geburt','Tod','Beisetzung','Schutzmerkmal','Merkmalsquelle','Notizen'],...state.graves.map(g=>keys.map(k=>g[k]))];download('melaten-grabregister.csv','\ufeff'+rows.map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8');};
$('#help').onclick=()=>openModal('Zum Arbeitsstand',`<div class="helptext"><p>Dieser Arbeitsplan basiert auf deiner hochgeladenen Melaten-Vorlage.</p><ul><li><strong>Vektorvorlage:</strong> Die Farbkonturen des Rasterplans wurden in SVG-Pfade umgewandelt. Der SVG enthält kein eingebettetes Rasterbild.</li><li><strong>Arbeitskarte:</strong> ${fields.length} Flächen wurden schematisch nachgezeichnet. Ihre Grenzen und Bezeichnungen sind vor fachlicher Verwendung zu prüfen. Rand-, Wege- und Teilflächen können unvollständig oder vereinfacht sein.</li><li><strong>Koordinaten:</strong> Lokale Bildkoordinaten, kein amtlicher Raumbezug. Abstände und Flächeninhalte sind nicht in Metern berechenbar.</li><li><strong>Verwaltung:</strong> Grabregister, Flächennotizen und Aufgaben liegen ausschließlich im lokalen Browser. Es gibt keine gemeinsame Datenbank, Benutzerverwaltung oder automatische Sicherung.</li><li><strong>Datensicherung:</strong> Exportiere regelmäßig JSON. Browserdaten löschen entfernt auch diese Einträge. Import ersetzt den aktuellen Datenstand.</li></ul><p><a href="melaten-vektor.svg" download>Vektorvorlage (SVG)</a> · <a href="melaten-flaechen.svg" download>Flurflächen (SVG)</a> · <a href="flaechen-lokal.csv" download>Flurflächen (CSV mit WKT)</a> · <a href="plan-data.json" download>Plan-Geometrien (JSON)</a></p></div>`);
render();const initial=location.hash.slice(1);if(['karte','register','aufgaben','analyse'].includes(initial))view(initial);
